window.CHUJI_DATA_3 = [{"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 1, "type": "reading", "en": "I don't know anyone at this party.", "zh": "这个宴会上的人我一个也不认识。", "audio": "chuji_l21_01.mp3", "localAudio": "audio_chunks/chuji_l21_01.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 2, "type": "reading", "en": "There's a strange man.", "zh": "有个陌生的男人。", "audio": "chuji_l21_02.mp3", "localAudio": "audio_chunks/chuji_l21_02.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 3, "type": "reading", "en": "He has a big nose and small ears.", "zh": "他长着大鼻子和小耳朵。", "audio": "chuji_l21_03.mp3", "localAudio": "audio_chunks/chuji_l21_03.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 4, "type": "reading", "en": "I don't know him.", "zh": "我不认识他。", "audio": "chuji_l21_04.mp3", "localAudio": "audio_chunks/chuji_l21_04.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 5, "type": "reading", "en": "There are two women.", "zh": "有两个女人。", "audio": "chuji_l21_05.mp3", "localAudio": "audio_chunks/chuji_l21_05.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 6, "type": "reading", "en": "They're wearing glasses.", "zh": "她们戴着眼镜。", "audio": "chuji_l21_06.mp3", "localAudio": "audio_chunks/chuji_l21_06.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 7, "type": "reading", "en": "I don't know them, either.", "zh": "我也不认识她们。", "audio": "chuji_l21_07.mp3", "localAudio": "audio_chunks/chuji_l21_07.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 8, "type": "reading", "en": "There is a cute young girl.", "zh": "有一位可爱的年轻女孩。", "audio": "chuji_l21_08.mp3", "localAudio": "audio_chunks/chuji_l21_08.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 9, "type": "reading", "en": "She has long hair and fair skin.", "zh": "她留着长发，皮肤白皙。", "audio": "chuji_l21_09.mp3", "localAudio": "audio_chunks/chuji_l21_09.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 10, "type": "reading", "en": "She's dancing with someone.", "zh": "她正和别人在跳舞。", "audio": "chuji_l21_10.mp3", "localAudio": "audio_chunks/chuji_l21_10.mp3", "b64": "", "src": "chuji"}, {"l": 321, "lt": "Lesson 21 I Don't Know Anyone 我谁都不认识", "i": 11, "type": "reading", "en": "I like her, but everyone else does, too.", "zh": "我喜欢她，但其他人也都喜欢她。", "audio": "chuji_l21_11.mp3", "localAudio": "audio_chunks/chuji_l21_11.mp3", "b64": "", "src": "chuji"}, {"l": 322, "lt": "Lesson 22 Do You Want to Dance? 你想跳舞吗？", "i": 1, "type": "dialog", "en": "Hello. Do you want to dance?", "zh": "你好。你想跳舞吗？", "audio": "chuji_l22_01.mp3", "localAudio": "audio_chunks/chuji_l22_01.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 322, "lt": "Lesson 22 Do You Want to Dance? 你想跳舞吗？", "i": 2, "type": "dialog", "en": "No, thanks.", "zh": "不，谢谢。", "audio": "chuji_l22_02.mp3", "localAudio": "audio_chunks/chuji_l22_02.mp3", "b64": "", "src": "chuji", "speaker": "Jane", "note": "说话人: Jane"}, {"l": 322, "lt": "Lesson 22 Do You Want to Dance? 你想跳舞吗？", "i": 3, "type": "dialog", "en": "Do you want a drink?", "zh": "你想喝一杯吗？", "audio": "chuji_l22_03.mp3", "localAudio": "audio_chunks/chuji_l22_03.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 322, "lt": "Lesson 22 Do You Want to Dance? 你想跳舞吗？", "i": 4, "type": "dialog", "en": "No, thank you.", "zh": "不，谢谢你。", "audio": "chuji_l22_04.mp3", "localAudio": "audio_chunks/chuji_l22_04.mp3", "b64": "", "src": "chuji", "speaker": "Jane", "note": "说话人: Jane"}, {"l": 322, "lt": "Lesson 22 Do You Want to Dance? 你想跳舞吗？", "i": 5, "type": "dialog", "en": "What do you want?", "zh": "那你想要什么？", "audio": "chuji_l22_05.mp3", "localAudio": "audio_chunks/chuji_l22_05.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 322, "lt": "Lesson 22 Do You Want to Dance? 你想跳舞吗？", "i": 6, "type": "dialog", "en": "I just want you to go away.", "zh": "我只希望你走开。", "audio": "chuji_l22_06.mp3", "localAudio": "audio_chunks/chuji_l22_06.mp3", "b64": "", "src": "chuji", "speaker": "Jane", "note": "说话人: Jane"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 1, "type": "reading", "en": "This is my English book.", "zh": "这是我的英文书。", "audio": "chuji_l23_01.mp3", "localAudio": "audio_chunks/chuji_l23_01.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 2, "type": "reading", "en": "It belongs to me.", "zh": "它属于我。", "audio": "chuji_l23_02.mp3", "localAudio": "audio_chunks/chuji_l23_02.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 3, "type": "reading", "en": "It is mine.", "zh": "它是我的。", "audio": "chuji_l23_03.mp3", "localAudio": "audio_chunks/chuji_l23_03.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 4, "type": "reading", "en": "That is your English book.", "zh": "那是你的英文书。", "audio": "chuji_l23_04.mp3", "localAudio": "audio_chunks/chuji_l23_04.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 5, "type": "reading", "en": "It belongs to you.", "zh": "它属于你。", "audio": "chuji_l23_05.mp3", "localAudio": "audio_chunks/chuji_l23_05.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 6, "type": "reading", "en": "It is yours.", "zh": "它是你的。", "audio": "chuji_l23_06.mp3", "localAudio": "audio_chunks/chuji_l23_06.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 7, "type": "reading", "en": "Those books aren't ours.", "zh": "那些书不是我们的。", "audio": "chuji_l23_07.mp3", "localAudio": "audio_chunks/chuji_l23_07.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 8, "type": "reading", "en": "They belong to those boys over there.", "zh": "它们属于那边那些男孩。", "audio": "chuji_l23_08.mp3", "localAudio": "audio_chunks/chuji_l23_08.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 9, "type": "reading", "en": "They are theirs.", "zh": "那是他们的。", "audio": "chuji_l23_09.mp3", "localAudio": "audio_chunks/chuji_l23_09.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 10, "type": "reading", "en": "Why do we all have different books?", "zh": "为什么我们大家的书都不一样？", "audio": "chuji_l23_10.mp3", "localAudio": "audio_chunks/chuji_l23_10.mp3", "b64": "", "src": "chuji"}, {"l": 323, "lt": "Lesson 23 The Book Is Mine 这本书是我的", "i": 11, "type": "reading", "en": "Because we belong to different classes.", "zh": "因为我们属于不同的班级。", "audio": "chuji_l23_11.mp3", "localAudio": "audio_chunks/chuji_l23_11.mp3", "b64": "", "src": "chuji"}, {"l": 324, "lt": "Lesson 24 It's Mine 它是我的", "i": 1, "type": "dialog", "en": "Whose test paper is this?", "zh": "这是谁的试卷？", "audio": "chuji_l24_01.mp3", "localAudio": "audio_chunks/chuji_l24_01.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 324, "lt": "Lesson 24 It's Mine 它是我的", "i": 2, "type": "dialog", "en": "It's mine, ma'am.", "zh": "是我的，老师。", "audio": "chuji_l24_02.mp3", "localAudio": "audio_chunks/chuji_l24_02.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 324, "lt": "Lesson 24 It's Mine 它是我的", "i": 3, "type": "dialog", "en": "And whose test paper is this?", "zh": "那么这又是谁的试卷？", "audio": "chuji_l24_03.mp3", "localAudio": "audio_chunks/chuji_l24_03.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 324, "lt": "Lesson 24 It's Mine 它是我的", "i": 4, "type": "dialog", "en": "It's Tony's, ma'am.", "zh": "是托尼的，老师。", "audio": "chuji_l24_04.mp3", "localAudio": "audio_chunks/chuji_l24_04.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 324, "lt": "Lesson 24 It's Mine 它是我的", "i": 5, "type": "dialog", "en": "And why are your answers exactly the same as his?", "zh": "那为什么你的答案和他一模一样呢？", "audio": "chuji_l24_05.mp3", "localAudio": "audio_chunks/chuji_l24_05.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 324, "lt": "Lesson 24 It's Mine 它是我的", "i": 6, "type": "dialog", "en": "Because Tony has eyes in the back of his head.", "zh": "因为托尼后脑勺长了眼睛。", "audio": "chuji_l24_06.mp3", "localAudio": "audio_chunks/chuji_l24_06.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 325, "lt": "Lesson 25 My Father 我的父亲", "i": 1, "type": "reading", "en": "My father does the same thing every morning.", "zh": "我父亲每天早晨都做同样的事。", "audio": "chuji_l25_01.mp3", "localAudio": "audio_chunks/chuji_l25_01.mp3", "b64": "", "src": "chuji"}, {"l": 325, "lt": "Lesson 25 My Father 我的父亲", "i": 2, "type": "reading", "en": "He gets up at six o'clock.", "zh": "他六点起床。", "audio": "chuji_l25_02.mp3", "localAudio": "audio_chunks/chuji_l25_02.mp3", "b64": "", "src": "chuji"}, {"l": 325, "lt": "Lesson 25 My Father 我的父亲", "i": 3, "type": "reading", "en": "He washes, brushes his teeth and combs his hair.", "zh": "他洗脸、刷牙、梳头发。", "audio": "chuji_l25_03.mp3", "localAudio": "audio_chunks/chuji_l25_03.mp3", "b64": "", "src": "chuji"}, {"l": 325, "lt": "Lesson 25 My Father 我的父亲", "i": 4, "type": "reading", "en": "Then, he puts on his clothes and eats breakfast.", "zh": "然后穿好衣服吃早餐。", "audio": "chuji_l25_04.mp3", "localAudio": "audio_chunks/chuji_l25_04.mp3", "b64": "", "src": "chuji"}, {"l": 325, "lt": "Lesson 25 My Father 我的父亲", "i": 5, "type": "reading", "en": "At six-thirty he listens to the news on the radio.", "zh": "六点半他收听广播里的新闻。", "audio": "chuji_l25_05.mp3", "localAudio": "audio_chunks/chuji_l25_05.mp3", "b64": "", "src": "chuji"}, {"l": 325, "lt": "Lesson 25 My Father 我的父亲", "i": 6, "type": "reading", "en": "At exactly seven o'clock he leaves the house.", "zh": "整整七点他就出门离开家。", "audio": "chuji_l25_06.mp3", "localAudio": "audio_chunks/chuji_l25_06.mp3", "b64": "", "src": "chuji"}, {"l": 325, "lt": "Lesson 25 My Father 我的父亲", "i": 7, "type": "reading", "en": "My father has very regular habits.", "zh": "我父亲有非常规律的生活习惯。", "audio": "chuji_l25_07.mp3", "localAudio": "audio_chunks/chuji_l25_07.mp3", "b64": "", "src": "chuji"}, {"l": 326, "lt": "Lesson 26 He Usually Plays Tennis 他通常打网球", "i": 1, "type": "dialog", "en": "What do you usually do on Sundays?", "zh": "你周日通常做些什么？", "audio": "chuji_l26_01.mp3", "localAudio": "audio_chunks/chuji_l26_01.mp3", "b64": "", "src": "chuji", "speaker": "Jeff", "note": "说话人: Jeff"}, {"l": 326, "lt": "Lesson 26 He Usually Plays Tennis 他通常打网球", "i": 2, "type": "dialog", "en": "I usually go for a walk in the mountains.", "zh": "我通常到山中走一走。", "audio": "chuji_l26_02.mp3", "localAudio": "audio_chunks/chuji_l26_02.mp3", "b64": "", "src": "chuji", "speaker": "Betty", "note": "说话人: Betty"}, {"l": 326, "lt": "Lesson 26 He Usually Plays Tennis 他通常打网球", "i": 3, "type": "dialog", "en": "Does your husband go with you?", "zh": "你先生跟你一块儿去吗？", "audio": "chuji_l26_03.mp3", "localAudio": "audio_chunks/chuji_l26_03.mp3", "b64": "", "src": "chuji", "speaker": "Jeff", "note": "说话人: Jeff"}, {"l": 326, "lt": "Lesson 26 He Usually Plays Tennis 他通常打网球", "i": 4, "type": "dialog", "en": "No. He doesn't.", "zh": "不，他不去的。", "audio": "chuji_l26_04.mp3", "localAudio": "audio_chunks/chuji_l26_04.mp3", "b64": "", "src": "chuji", "speaker": "Betty", "note": "说话人: Betty"}, {"l": 326, "lt": "Lesson 26 He Usually Plays Tennis 他通常打网球", "i": 5, "type": "dialog", "en": "What does he do?", "zh": "那他通常做什么？", "audio": "chuji_l26_05.mp3", "localAudio": "audio_chunks/chuji_l26_05.mp3", "b64": "", "src": "chuji", "speaker": "Jeff", "note": "说话人: Jeff"}, {"l": 326, "lt": "Lesson 26 He Usually Plays Tennis 他通常打网球", "i": 6, "type": "dialog", "en": "He usually plays tennis.", "zh": "他通常去打网球。", "audio": "chuji_l26_06.mp3", "localAudio": "audio_chunks/chuji_l26_06.mp3", "b64": "", "src": "chuji", "speaker": "Betty", "note": "说话人: Betty"}, {"l": 327, "lt": "Lesson 27 Jack and His Dog 杰克和他的狗", "i": 1, "type": "reading", "en": "Jack seldom gets together with his friends.", "zh": "杰克很少和朋友们聚在一起。", "audio": "chuji_l27_01.mp3", "localAudio": "audio_chunks/chuji_l27_01.mp3", "b64": "", "src": "chuji"}, {"l": 327, "lt": "Lesson 27 Jack and His Dog 杰克和他的狗", "i": 2, "type": "reading", "en": "He usually stays at home with his pet dog, Lucky.", "zh": "他通常跟他的爱犬乐奇待在家里。", "audio": "chuji_l27_02.mp3", "localAudio": "audio_chunks/chuji_l27_02.mp3", "b64": "", "src": "chuji"}, {"l": 327, "lt": "Lesson 27 Jack and His Dog 杰克和他的狗", "i": 3, "type": "reading", "en": "They sometimes go for long walks in the park.", "zh": "他们有时候在公园里散步，走上好一阵子。", "audio": "chuji_l27_03.mp3", "localAudio": "audio_chunks/chuji_l27_03.mp3", "b64": "", "src": "chuji"}, {"l": 327, "lt": "Lesson 27 Jack and His Dog 杰克和他的狗", "i": 4, "type": "reading", "en": "Although Jack is often alone, he is never lonely.", "zh": "虽然杰克常常独处，但他从不感到孤单。", "audio": "chuji_l27_04.mp3", "localAudio": "audio_chunks/chuji_l27_04.mp3", "b64": "", "src": "chuji"}, {"l": 327, "lt": "Lesson 27 Jack and His Dog 杰克和他的狗", "i": 5, "type": "reading", "en": "He always tells his friends that a dog is man's best friend.", "zh": "他总是对朋友说，狗是人类最好的朋友。", "audio": "chuji_l27_05.mp3", "localAudio": "audio_chunks/chuji_l27_05.mp3", "b64": "", "src": "chuji"}, {"l": 328, "lt": "Lesson 28 I Always Walk 我都是走路去", "i": 1, "type": "dialog", "en": "How do you go to school, Judy?", "zh": "朱迪，你是怎么去上学的？", "audio": "chuji_l28_01.mp3", "localAudio": "audio_chunks/chuji_l28_01.mp3", "b64": "", "src": "chuji", "speaker": "Chris", "note": "说话人: Chris"}, {"l": 328, "lt": "Lesson 28 I Always Walk 我都是走路去", "i": 2, "type": "dialog", "en": "I usually take a bus, but sometimes I ride my bicycle. What about you?", "zh": "我通常坐公交车，但有时也骑自行车。你呢？", "audio": "chuji_l28_02.mp3", "localAudio": "audio_chunks/chuji_l28_02.mp3", "b64": "", "src": "chuji", "speaker": "Judy", "note": "说话人: Judy"}, {"l": 328, "lt": "Lesson 28 I Always Walk 我都是走路去", "i": 3, "type": "dialog", "en": "I live near our school, so I always walk.", "zh": "我住得离学校近，所以我总是走路去。", "audio": "chuji_l28_03.mp3", "localAudio": "audio_chunks/chuji_l28_03.mp3", "b64": "", "src": "chuji", "speaker": "Chris", "note": "说话人: Chris"}, {"l": 328, "lt": "Lesson 28 I Always Walk 我都是走路去", "i": 4, "type": "dialog", "en": "You're lucky.", "zh": "你真幸运。", "audio": "chuji_l28_04.mp3", "localAudio": "audio_chunks/chuji_l28_04.mp3", "b64": "", "src": "chuji", "speaker": "Judy", "note": "说话人: Judy"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 1, "type": "reading", "en": "There are holes in Dick's shoes.", "zh": "迪克的鞋子上有破洞。", "audio": "chuji_l29_01.mp3", "localAudio": "audio_chunks/chuji_l29_01.mp3", "b64": "", "src": "chuji"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 2, "type": "reading", "en": "He needs new shoes.", "zh": "他需要一双新鞋。", "audio": "chuji_l29_02.mp3", "localAudio": "audio_chunks/chuji_l29_02.mp3", "b64": "", "src": "chuji"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 3, "type": "reading", "en": "Dick doesn't want cheap shoes.", "zh": "迪克不想要便宜的鞋。", "audio": "chuji_l29_03.mp3", "localAudio": "audio_chunks/chuji_l29_03.mp3", "b64": "", "src": "chuji"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 4, "type": "reading", "en": "He wants expensive shoes, but he doesn't have any money.", "zh": "他想要昂贵的鞋子，但他一点钱也没有。", "audio": "chuji_l29_04.mp3", "localAudio": "audio_chunks/chuji_l29_04.mp3", "b64": "", "src": "chuji"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 5, "type": "reading", "en": "He needs a job.", "zh": "他需要一份工作。", "audio": "chuji_l29_05.mp3", "localAudio": "audio_chunks/chuji_l29_05.mp3", "b64": "", "src": "chuji"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 6, "type": "reading", "en": "He is looking for one, but he isn't having any luck.", "zh": "他正在找工作，但运气总是不太好。", "audio": "chuji_l29_06.mp3", "localAudio": "audio_chunks/chuji_l29_06.mp3", "b64": "", "src": "chuji"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 7, "type": "reading", "en": "No one wants to give him a job because his shoes have holes in them.", "zh": "没有人愿意给他工作，因为他的鞋子破了洞。", "audio": "chuji_l29_07.mp3", "localAudio": "audio_chunks/chuji_l29_07.mp3", "b64": "", "src": "chuji"}, {"l": 329, "lt": "Lesson 29 Poor Dick 可怜的迪克", "i": 8, "type": "reading", "en": "Poor Dick!", "zh": "可怜的迪克！", "audio": "chuji_l29_08.mp3", "localAudio": "audio_chunks/chuji_l29_08.mp3", "b64": "", "src": "chuji"}, {"l": 330, "lt": "Lesson 30 Money Doesn't Grow on Trees 挣钱是很辛苦的", "i": 1, "type": "dialog", "en": "Mother, can you buy me a new bike?", "zh": "妈妈，你能给我买一辆新自行车吗？", "audio": "chuji_l30_01.mp3", "localAudio": "audio_chunks/chuji_l30_01.mp3", "b64": "", "src": "chuji", "speaker": "Sam", "note": "说话人: Sam"}, {"l": 330, "lt": "Lesson 30 Money Doesn't Grow on Trees 挣钱是很辛苦的", "i": 2, "type": "dialog", "en": "No, Sam. I can't.", "zh": "不行，萨姆。我买不起。", "audio": "chuji_l30_02.mp3", "localAudio": "audio_chunks/chuji_l30_02.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 330, "lt": "Lesson 30 Money Doesn't Grow on Trees 挣钱是很辛苦的", "i": 3, "type": "dialog", "en": "But all my friends have new bicycles.", "zh": "但是我所有的朋友都有新车。", "audio": "chuji_l30_03.mp3", "localAudio": "audio_chunks/chuji_l30_03.mp3", "b64": "", "src": "chuji", "speaker": "Sam", "note": "说话人: Sam"}, {"l": 330, "lt": "Lesson 30 Money Doesn't Grow on Trees 挣钱是很辛苦的", "i": 4, "type": "dialog", "en": "You can ride their bikes.", "zh": "你可以骑他们的车子呀！", "audio": "chuji_l30_04.mp3", "localAudio": "audio_chunks/chuji_l30_04.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 330, "lt": "Lesson 30 Money Doesn't Grow on Trees 挣钱是很辛苦的", "i": 5, "type": "dialog", "en": "Why can't I have a new bike?", "zh": "为什么我就不能有一辆新车呢？", "audio": "chuji_l30_05.mp3", "localAudio": "audio_chunks/chuji_l30_05.mp3", "b64": "", "src": "chuji", "speaker": "Sam", "note": "说话人: Sam"}, {"l": 330, "lt": "Lesson 30 Money Doesn't Grow on Trees 挣钱是很辛苦的", "i": 6, "type": "dialog", "en": "Because money doesn't grow on trees.", "zh": "因为钱不会长在树上嘛（挣钱是很辛苦的）。", "audio": "chuji_l30_06.mp3", "localAudio": "audio_chunks/chuji_l30_06.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}];